/* Shared presentation and navigation only. Business permissions remain server enforced. */
(() => {
 'use strict';
 const root=document.documentElement;
 try {const value=localStorage.getItem('bemo-theme');if(['light','dark'].includes(value))root.dataset.theme=value;}catch(_){}
 const words={home:['الرئيسية','Home'],shop:['تسوق','Shop'],buyer:['السلة والطلب','Cart & checkout'],seller:['المتجر','Store'],orders:['طلباتي','My orders'],notifications:['الإشعارات','Notifications'],support:['المساعدة','Help'],account:['حسابي','My account'],theme:['المظهر الداكن','Dark appearance'],categories:['تسوق حسب التصنيف','Shop by category'],electronics:['الإلكترونيات','Electronics'],fashion:['الأزياء','Fashion'],homeGoods:['المنزل والمعيشة','Home & living'],beauty:['الجمال','Beauty'],sports:['الرياضة','Sports'],other:['اكتشافات أخرى','More finds'],products:['المنتجات والمخزون','Products & inventory'],delivery:['رسوم التوصيل','Delivery fees'],store:['بيانات المتجر','Store profile'],manage:['المتجر','STORE'],cod:['الدفع عند الاستلام · عمولة المنصة 0%','Cash on delivery · 0% platform commission'],sellerOrders:['طلبات المتجر','Store orders'],navigation:['التنقل الرئيسي','Main navigation']};
 words.balance=['الرصيد والاستقطاع','Balance & commission'];words.switchBuyer=['التبديل إلى التسوق','Switch to shopping'];words.switchSeller=['المتجر','Store'];words.openStore=['المتجر','Store'];words.dashboard=['لوحة المتجر','Dashboard'];words.addresses=['عناويني','My addresses'];
 const paths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',shop:'M3 8h18l-2-5H5L3 8Zm1 0v13h16V8M9 21v-7h6v7',buyer:'M3 4h2l3 12h11l2-8H6M9 20h.01M18 20h.01',seller:'M4 3h16v18H4ZM8 8h8M8 12h8M8 16h4',orders:'m3 7 9-4 9 4v11l-9 4-9-4V7Zm0 0 9 5 9-5M12 12v10',notifications:'M6 8a6 6 0 0 1 12 0v7l3 3H3l3-3V8m4 13h4',account:'M5 21v-2a7 7 0 0 1 14 0v2M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8',theme:'M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11',support:'M12 17h.01M9 9a3 3 0 1 1 4 3v2M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',electronics:'M7 2h10v20H7ZM11 18h2',fashion:'m8 3 4 2 4-2 6 4-3 5-3-2v12H8V10l-3 2-3-5Z',homeGoods:'M3 12h18v8H3Zm2 0V6h14v6M5 20v2M19 20v2',beauty:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',sports:'m3 6 3-3 15 15-3 3ZM2 10l8-8M14 22l8-8',other:'M3 3h7v7H3Zm11 0h7v7h-7ZM3 14h7v7H3Zm11 0h7v7h-7Z'};
 paths.dashboard='M3 3h7v7H3Zm11 0h7v5h-7ZM3 14h7v7H3Zm11-2h7v9h-7Z';paths.products=paths.orders;paths.sellerOrders=paths.orders;paths.store=paths.shop;paths.delivery='M2 5h12v13H2Zm12 5h4l4 5v3h-8M6 16a3 3 0 1 0 0 6 3 3 0 0 0 0-6M18 16a3 3 0 1 0 0 6 3 3 0 0 0 0-6';
 const lang=()=>root.lang==='en'?'en':'ar',t=k=>(words[k]||[k,k])[lang()==='ar'?0:1];
 function icon(key){const s=document.createElementNS('http://www.w3.org/2000/svg','svg');s.setAttribute('viewBox','0 0 24 24');s.setAttribute('aria-hidden','true');const p=document.createElementNS('http://www.w3.org/2000/svg','path');p.setAttribute('d',paths[key]||paths.shop);s.append(p);return s;}
 function link(key,file,params={},hash=''){const a=document.createElement('a');a.dataset.uiLabel=key;a.dataset.uiFile=file;a.dataset.uiParams=JSON.stringify(params);a.dataset.uiHash=hash;a.append(icon(key));const text=document.createElement('span');a.append(text);return a;}
 function refresh(){document.querySelectorAll('[data-ui-label]').forEach(n=>{const span=n.querySelector('span');if(span)span.textContent=t(n.dataset.uiLabel);else n.textContent=t(n.dataset.uiLabel);if(n.dataset.uiFile)n.href=n.dataset.uiFile+'?'+new URLSearchParams({lang:lang(),...JSON.parse(n.dataset.uiParams||'{}')})+(n.dataset.uiHash||'');});const button=document.getElementById('themeButton');if(button){button.setAttribute('aria-pressed',String(root.dataset.theme==='dark'));button.setAttribute('aria-label',t('theme'));button.title=t('theme');}document.querySelectorAll('.workspace-nav,.workspace-mobile').forEach(n=>n.setAttribute('aria-label',t('navigation')));}
 function start(){
  const path=location.pathname.split('/').pop().replace(/\.html$/,'')||'index';
  const view=new URL(location.href).searchParams.get('view'),sellerSpace=['merchant','seller','store-editor','balance'].includes(path)||(path==='orders'&&(view==='seller'||new URL(location.href).searchParams.get('space')==='seller'));root.dataset.workspace=sellerSpace?'seller':'buyer';
  const host=document.querySelector('.header-row nav')||document.querySelector('.header-actions');
  if(sellerSpace&&host)host.querySelectorAll('a[data-route="market.html"],#cartLink').forEach(a=>a.hidden=true);
  if(host){const b=document.createElement('button');b.type='button';b.id='themeButton';b.className='theme-button';b.append(icon('theme'));b.addEventListener('click',()=>{root.dataset.theme=root.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('bemo-theme',root.dataset.theme);}catch(_){}refresh();});host.append(b);}
  if(path!=='index'){
   const header=document.querySelector('.account-header');if(header){const nav=document.createElement('nav');nav.className='workspace-nav';const inner=document.createElement('div');inner.className='account-container workspace-nav-inner';for(const [key,file,params] of (sellerSpace? [['dashboard','seller.html',{}],['products','merchant.html',{}],['sellerOrders','orders.html',{view:'seller'}],['balance','balance.html',{}],['store','store-editor.html',{}],['support','help.html',{}]] : [['home','index.html',{}],['shop','market.html',{}],['buyer','market.html',{view:'cart'}],['orders','orders.html',{view:'buyer'}],['addresses','addresses.html',{}],['support','help.html',{}]])){const a=link(key,file,params);if((['merchant','seller','store-editor'].includes(path)&&key==='seller')||(path==='orders'&&key==='orders')||(path==='market'&&key===(new URL(location.href).searchParams.get('view')==='cart'?'buyer':'shop')))a.setAttribute('aria-current','page');inner.append(a);}nav.append(inner);header.after(nav);}
   const bottom=document.createElement('nav');bottom.className='workspace-mobile';for(const [key,file,params] of (sellerSpace? [['dashboard','seller.html',{}],['products','merchant.html',{}],['sellerOrders','orders.html',{view:'seller'}],['balance','balance.html',{}],['account','account.html',{}]] : [['home','index.html',{}],['shop','market.html',{}],['buyer','market.html',{view:'cart'}],['orders','orders.html',{view:'buyer'}],['account','account.html',{}]]))bottom.append(link(key,file,params));document.body.append(bottom);
  }
  if(host){const switcher=link(sellerSpace?'switchBuyer':'openStore',sellerSpace?'market.html':'seller.html');switcher.className='workspace-switch';host.append(switcher);if(!sellerSpace&&window.BemoAccount)window.BemoAccount.subscribe(s=>{switcher.dataset.uiLabel=s.phase==='ready'&&s.store?'switchSeller':'openStore';switcher.dataset.uiFile=s.phase==='ready'&&s.store?'seller.html':'merchant.html';refresh();});}
  const sidebar=document.getElementById('sellerNavigation');if(sidebar){const title=document.createElement('p');title.dataset.uiLabel='manage';sidebar.append(title);for(const [key,file,params,hash] of [['dashboard','seller.html',{},''],['products','merchant.html',{},'#sellerProducts'],['sellerOrders','orders.html',{view:'seller'},''],['delivery','merchant.html',{},'#sellerDelivery'],['store','store-editor.html',{},''],['balance','balance.html',{},''],['notifications','orders.html',{view:'notifications',space:'seller'},''],['support','help.html',{},'']])sidebar.append(link(key,file,params,hash));const note=document.createElement('div');note.className='seller-cod-note';note.dataset.uiLabel='cod';sidebar.append(note);}
  words.staffSupport=['حالات الدعم','Support cases'];words.financeAdmin=['مركز الإدارة','Admin center'];
  if(host&&window.BemoAccount){let accessEpoch=0;const staff=document.createElement('span');staff.className='staff-links';host.append(staff);window.BemoAccount.subscribe(async s=>{const ticket=++accessEpoch;staff.replaceChildren();if(s.phase!=='ready')return;try{const r=await window.BemoAccount.orderScope().request('bemo_workspace_access');if(ticket!==accessEpoch||r.error)return;if(r.data.support)staff.append(link('staffSupport','orders.html',{view:'support'}));if(r.data.admin)staff.append(link('financeAdmin','admin.html'));refresh();}catch(_){}});}
  const rail=document.getElementById('homeCategoryRail');if(rail){const title=document.createElement('h2');title.dataset.uiLabel='categories';rail.append(title);for(const [key,category] of [['electronics','electronics'],['fashion','fashion'],['homeGoods','home'],['beauty','beauty'],['sports','sports'],['other','other']])rail.append(link(key,'market.html',{category}));}
  function activeNavigation(){const current=new URL(location.href),cart=current.searchParams.get('view')==='cart';document.querySelectorAll('.workspace-nav a,.workspace-mobile a').forEach(a=>{const key=a.dataset.uiLabel;const active=(sellerSpace&&((path==='seller'&&key==='dashboard')||(path==='merchant'&&key==='products')||(path==='orders'&&key==='sellerOrders')||(path==='balance'&&key==='balance')||(path==='store-editor'&&key==='store')))||(path==='index'&&key==='home')||(path==='market'&&key===(cart?'buyer':'shop'))||(['merchant','seller','store-editor'].includes(path)&&key==='seller')||(path==='addresses'&&key==='addresses')||(path==='account'&&key==='account')||(path==='help'&&key==='support')||(path==='orders'&&key===(current.searchParams.get('view')==='notifications'?'notifications':'orders'));if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
  function sidebarActive(){if(!sidebar)return;sidebar.querySelectorAll('a').forEach(a=>{const file=a.dataset.uiFile.replace(/\.html$/,''),hash=a.dataset.uiHash||'',match=file===path&&(path!=='merchant'||hash===(location.hash==='#sellerDelivery'?'#sellerDelivery':'#sellerProducts'));if(match)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}refresh();activeNavigation();sidebarActive();window.addEventListener('hashchange',sidebarActive);window.addEventListener('bemo:view',activeNavigation);new MutationObserver(()=>{refresh();activeNavigation();}).observe(root,{attributes:true,attributeFilter:['lang']});
 }
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start);else start();
})();
